/**
 * ErrorCode
 *
 * Stable, machine-readable names for the errors a client acts on (ADR-0129 point 6).
 *
 * `message` and `detail` are for people and may be reworded at any time; a client that needs
 * to *do* something — prompt for a token, drop a dead profile — switches on `code`. Add a member
 * when a client needs to distinguish a case, not for every exception class: most errors are
 * shown, not handled. Documented in `docs/ERROR-CONTRACTS.md`.
 */
export type ErrorCode = 'SERVER_TOKEN_REQUIRED' | 'INVALID_PROFILE' | 'SCAN_IN_PROGRESS' | 'ANALYSIS_IN_PROGRESS';

/**
 * ErrorEnvelope
 *
 * The shape every error response takes (ADR-0007).
 *
 * Mirrors `create_error_response` in `app/main.py` exactly. Every handler funnels through it:
 * validation errors, `FamiliarError` subclasses, `HTTPException`, SQLAlchemy failures and the
 * catch-all 500.
 *
 * Modelled here because it was previously described nowhere. The schema documented only 200 and
 * FastAPI's automatic 422 — and that 422 was actively wrong, because the validation handler is
 * overridden to emit *this* shape rather than `{"detail": [...]}`. A generated client therefore
 * had exactly one error model and it was the one the server never sends.
 *
 * `detail` and `request_id` are optional because they are **omitted** when absent rather than
 * sent as null, so a client must treat them as missing keys and not as nullable values.
 */
export type ErrorEnvelope = {
    /**
     * Stable machine-readable name, present on the errors a client acts on (ADR-0129 point 6). Switch on this, never on `message`.
     */
    code?: ErrorCode;
    /**
     * Detail
     *
     * Extra context. Present for validation errors and, in debug builds, for 500s.
     */
    detail?: string | null;
    /**
     * Error
     *
     * Always true; lets a client discriminate without status.
     */
    error?: boolean;
    /**
     * Message
     *
     * Human-readable summary, safe to surface.
     */
    message: string;
    /**
     * Request Id
     *
     * Correlates with the x-request-id response header and the server log.
     */
    request_id?: string | null;
    /**
     * Status Code
     *
     * Repeats the HTTP status, for logs and clients that lose it.
     */
    status_code: number;
};

